$content = Get-Content "app/src/main/java/com/attendance/app/student/ui/StudentClassDetailScreen.kt" -Raw
$content = $content -replace "(?m)^(\s*val todayStatus by attendanceViewModel.todayStatus.collectAsState\(\))", "`$1`n    val currentBackStackEntry = navController.currentBackStackEntry`n    val verifiedClassId = currentBackStackEntry?.savedStateHandle?.getStateFlow<String?>(`"verified_class_id`", null)?.collectAsState()?.value`n`n    androidx.compose.runtime.LaunchedEffect(verifiedClassId) {`n        if (verifiedClassId != null && verifiedClassId == classId) {`n            currentBackStackEntry.savedStateHandle.remove<String>(`"verified_class_id`")`n            attendanceViewModel.onFaceVerificationSuccess(classId, context)`n        }`n    }"
Set-Content "app/src/main/java/com/attendance/app/student/ui/StudentClassDetailScreen.kt" $content
